using FluentValidation;
namespace FintechApp.Requests.SignUp { public class UpdateSignUpRequest { public int SignUpID { get; set; } public string MobileNumber { get; set; } = string.Empty; public string PANNo { get; set; } = string.Empty; public string ReferralCode { get; set; } = string.Empty; public string EmployeeID { get; set; } = string.Empty; public string OrderID { get; set; } = string.Empty; public string ProfileID { get; set; } = string.Empty; public string RedirectURL { get; set; } = string.Empty; public string Status { get; set; } = string.Empty; public string PinCode { get; set; } = string.Empty; } public class UpdateSignUpRequestValidator : AbstractValidator<UpdateSignUpRequest> { public UpdateSignUpRequestValidator() { RuleFor(x => x.SignUpID).GreaterThan(0); } } }
